// ─── PROFILE SCREEN ────────────────────────────────────────────────────────
const ProfileScreen = ({ profile, setProfile, songs, profileBanner, setProfileBanner }) => {
  const fileRef = useRef();
  const [frameOpen, setFrameOpen] = useState(false);
  const levelInfo = getLevelInfo(profile.xp);
  const [editing, setEditing] = useState(false);
  const [tmpName, setTmpName] = useState(profile.name);
  const [tmpBio,  setTmpBio]  = useState(profile.bio);

  const handleAvatar = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const r = new FileReader();
    r.onload = (ev) => setProfile(p => ({ ...p, avatar: ev.target.result }));
    r.readAsDataURL(file);
  };

  const stats = [
    { label: "Songs", value: songs.length },
    { label: "Liked", value: songs.filter(s => s.liked).length },
    { label: "XP",    value: profile.xp.toLocaleString() },
    { label: "Level", value: `LVL ${levelInfo.level.toLocaleString()}` },
  ];

  return (
    <div>
      {/* Hero card */}
      <div style={{ position: "relative", background: profileBanner?.image ? `linear-gradient(180deg,rgba(var(--bg-rgb),0.2) 0%,rgba(var(--bg-rgb),0.88) 100%), url(${profileBanner.image}) center/cover no-repeat` : "linear-gradient(160deg,var(--hero1) 0%,var(--hero2) 60%,var(--panel) 100%)", borderRadius: 20, padding: profileBanner?.image ? "64px 18px 18px" : "22px 18px 18px", marginBottom: 14 }}>
        <label aria-label="Ubah banner profil" style={{ position: "absolute", top: 12, right: 12, width: 34, height: 34, borderRadius: "50%", background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "#fff" }}>
          <IcCamera s={15} />
          <input type="file" accept="image/*" style={{ display: "none" }} onChange={async e => { const f = e.target.files?.[0]; e.target.value = ""; if (f) { try { const u = await readImage(f, 1000); setProfileBanner({ image: u }); } catch {} } }} />
        </label>
        {profileBanner?.image && <button aria-label="Hapus foto banner" onClick={() => setProfileBanner({ image: null })} style={{ position: "absolute", top: 12, right: 54, width: 34, height: 34, borderRadius: "50%", background: "rgba(0,0,0,0.45)", border: "none", color: "#fff", cursor: "pointer", fontSize: 13 }}><IcClose s={15} /></button>}
        <div style={{ display: "flex", alignItems: "flex-start", gap: 14 }}>
          <div style={{ position: "relative" }}>
            <AvatarFrame profile={profile} size={84} />
            <button onClick={() => fileRef.current?.click()} style={{
              position: "absolute", bottom: 6, right: 22, width: 24, height: 24,
              borderRadius: "50%", background: "var(--accent)", border: "2px solid var(--bg)",
              cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: "#fff",
            }}><IcCamera s={11} /></button>
            <input ref={fileRef} type="file" accept="image/*" onChange={handleAvatar} style={{ display: "none" }} />
            {frameOpen && (
              <div onClick={() => setFrameOpen(false)} style={{ position: "fixed", inset: 0, zIndex: 250, background: "rgba(0,0,0,0.72)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
                <div role="dialog" aria-modal="true" aria-label="Pilih bingkai" onClick={e => e.stopPropagation()} style={{ width: "100%", maxWidth: 400, maxHeight: "86dvh", overflowY: "auto", background: "var(--panel)", borderRadius: 24, padding: 18, boxShadow: "0 24px 60px rgba(0,0,0,0.6)" }}>
                  <div className="disp" style={{ fontSize: 20, fontWeight: 700, color: "#fff", marginBottom: 14 }}>Pilih bingkai</div>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
                    {FRAMES.map(f => {
                      const on = (profile.frame || "basic") === f.id;
                      return (
                        <button key={f.id} aria-pressed={on} onClick={() => setProfile(p => ({ ...p, frame: f.id }))} style={frameTile(on)}>
                          <AvatarFrame profile={{ ...profile, frame: f.id }} size={58} />
                          <span style={{ fontSize: 12, fontWeight: 600 }}>{f.name}</span>
                        </button>
                      );
                    })}
                                      </div>
                                    <button onClick={() => setFrameOpen(false)} style={{ width: "100%", marginTop: 14, background: "var(--accent)", border: "none", borderRadius: 12, padding: 12, fontSize: 14, fontWeight: 700, color: "#fff", cursor: "pointer" }}>Selesai</button>
                </div>
              </div>
            )}
          </div>

          <div style={{ flex: 1, minWidth: 0 }}>
            {editing ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
                <input value={tmpName} onChange={e => setTmpName(e.target.value)}
                  style={{ width: "100%", boxSizing: "border-box", background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.2)", borderRadius: 8, padding: "6px 10px", fontSize: 15, fontWeight: 700, color: "#fff", outline: "none" }} />
                <input value={tmpBio} onChange={e => setTmpBio(e.target.value)}
                  style={{ width: "100%", boxSizing: "border-box", background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.2)", borderRadius: 8, padding: "6px 10px", fontSize: 12, color: "rgba(255,255,255,0.6)", outline: "none" }} />
                <div style={{ display: "flex", gap: 7 }}>
                  <button onClick={() => { setProfile(p => ({ ...p, name: tmpName, bio: tmpBio })); setEditing(false); }}
                    style={{ background: "var(--accent)", border: "none", borderRadius: 8, padding: "6px 14px", fontSize: 12, fontWeight: 600, color: "#fff", cursor: "pointer" }}>Save</button>
                  <button onClick={() => setEditing(false)}
                    style={{ background: "rgba(255,255,255,0.1)", border: "none", borderRadius: 8, padding: "6px 14px", fontSize: 12, color: "rgba(255,255,255,0.6)", cursor: "pointer" }}>Cancel</button>
                </div>
              </div>
            ) : (
              <>
                <div className="disp" style={{ fontSize: 22, fontWeight: 700, color: "#fff" }}>{profile.name}</div>
                <div style={{ fontSize: 12, color: "rgba(255,255,255,0.64)", marginTop: 3, lineHeight: 1.4 }}>{profile.bio}</div>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}><button onClick={() => setEditing(true)} style={{
                  marginTop: 10, background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.15)",
                  borderRadius: 8, padding: "6px 12px", fontSize: 12, color: "#fff", cursor: "pointer",
                  display: "flex", alignItems: "center", gap: 5,
                }}><IcEdit s={12} /> Edit</button>
                <button onClick={() => setFrameOpen(true)} aria-haspopup="dialog" style={{ marginTop: 10, background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.15)", borderRadius: 8, padding: "6px 12px", fontSize: 12, color: "#fff", cursor: "pointer" }}>Bingkai</button>
              </div>
              </>
            )}
          </div>
        </div>

        {/* Level */}
        <div style={{ marginTop: 18, background: "rgba(255,255,255,0.06)", borderRadius: 12, padding: "11px 13px" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 7 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
              <LevelBadge level={levelInfo} size={32} />
              <span style={{ fontSize: 14, fontWeight: 700, color: "#fff" }}>Lv {levelInfo.level.toLocaleString()} · {levelInfo.name}</span>
            </div>
            <span style={{ fontSize: 11, color: "rgba(255,255,255,0.64)" }}>{levelInfo.xp.toLocaleString()} XP</span>
          </div>
          <XPBar pct={levelInfo.levelPct} color={levelInfo.color} height={7} />
          <div style={{ display: "flex", justifyContent: "space-between", marginTop: 5 }}>
            <span style={{ fontSize: 10, color: "rgba(255,255,255,0.64)" }}>Lv {levelInfo.level.toLocaleString()}</span>
            <span style={{ fontSize: 10, color: "rgba(255,255,255,0.64)" }}>{levelInfo.isMax ? "MAX" : `Lv ${(levelInfo.level + 1).toLocaleString()}`}</span>
          </div>
        </div>
      </div>

      {/* Stats */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 14 }}>
        {stats.map(s => (
          <div key={s.label} style={{ background: "rgba(255,255,255,0.055)", border: "1px solid rgba(255,255,255,0.08)", borderRadius: 18, padding: "14px 16px" }}>
            <div style={{ fontSize: 20, fontWeight: 700, color: "#fff" }}>{s.value}</div>
            <div style={{ fontSize: 11, color: "rgba(255,255,255,0.64)", marginTop: 2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Milestones */}
      <div style={{ background: "rgba(255,255,255,0.06)", borderRadius: 20, padding: "14px", border: "1px solid rgba(255,255,255,0.06)" }}>
        <div className="disp" style={{ fontSize: 18, fontWeight: 700, color: "#fff", marginBottom: 14 }}>Level milestones</div>
        {LEVELS.map((l, i) => {
          const reached = profile.xp >= l.min;
          return (
            <div key={l.name} style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: i < LEVELS.length - 1 ? 12 : 0 }}>
              <LevelBadge level={l} size={34} dim={!reached} />
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 13, fontWeight: 600, color: reached ? "#fff" : "rgba(255,255,255,0.38)" }}>{l.name}</div>
                <div style={{ fontSize: 11, color: "rgba(255,255,255,0.64)" }}>Lv {(Math.floor(l.min / XP_PER_LEVEL) + 1).toLocaleString()} · {l.min.toLocaleString()} XP</div>
              </div>
              {reached && <span style={{ display: "flex", color: l.color }}><IcCheck s={16} /></span>}
            </div>
          );
        })}
      </div>
    </div>
  );
};

