// ─── FLOATING PLAYER (Library + Online) ───────────────────────────────────
const FloatingPlayer = ({ s }) => {
  if (!s) return null;
  const pct = s.duration ? Math.min(100, (s.progress / s.duration) * 100) : 0;
  const btn = { background: "none", border: "none", color: "#fff", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", padding: 0 };
  return (
    <div style={{ position: "fixed", bottom: "calc(env(safe-area-inset-bottom,0px) + 86px)", left: 0, right: 0, zIndex: 60, padding: "0 12px", pointerEvents: "none" }}>
      <div key={s.key} style={{
        pointerEvents: "auto", position: "relative", overflow: "hidden", borderRadius: 24,
        background: "linear-gradient(135deg, var(--mini), rgba(var(--bg-rgb),0.97))",
        backdropFilter: "blur(26px)", WebkitBackdropFilter: "blur(26px)",
        border: "1px solid rgba(255,255,255,0.14)",
        boxShadow: "0 18px 46px rgba(0,0,0,0.55), 0 0 0 1px rgba(var(--accent-rgb),0.14), inset 0 1px 0 rgba(255,255,255,0.1)",
        animation: "fpIn .35s cubic-bezier(.22,1,.36,1) both",
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 11, padding: "10px 10px 12px 10px" }}>
          {/* Art + equalizer */}
          <div onClick={s.onExpand || undefined} style={{ position: "relative", width: 48, height: 48, flexShrink: 0, cursor: s.onExpand ? "pointer" : "default" }}>
            {s.thumb
              ? <div style={{ width: 48, height: 48, borderRadius: 14, background: `url(${s.thumb}) center/cover`, boxShadow: "0 4px 14px rgba(0,0,0,.45)" }} />
              : <AlbumArt song={s.song} size={48} style={{ borderRadius: 14 }} />}
            {s.playing && (
              <div aria-hidden="true" style={{ position: "absolute", right: 4, bottom: 4, display: "flex", alignItems: "flex-end", gap: 2, height: 12, padding: "2px 3px", borderRadius: 5, background: "rgba(0,0,0,.55)" }}>
                {[0, 1, 2].map(k => <span key={k} style={{ width: 2.5, height: 10, borderRadius: 2, background: "var(--accent-soft)", transformOrigin: "bottom", animation: `eqBar ${0.7 + k * 0.18}s ease-in-out ${-k * 0.2}s infinite` }} />)}
              </div>
            )}
          </div>

          {/* Title */}
          <div onClick={s.onExpand || undefined} style={{ flex: 1, minWidth: 0, cursor: s.onExpand ? "pointer" : "default" }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: "#fff", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{s.title}</div>
            <div style={{ fontSize: 11.5, color: "rgba(255,255,255,0.58)", marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
              <span style={{ color: "var(--accent-soft)", fontWeight: 600 }}>{s.kind === "online" ? "Online" : "Library"}</span>
              {s.subtitle ? ` · ${s.subtitle}` : ""}
            </div>
          </div>

          {/* Controls */}
          <div style={{ display: "flex", alignItems: "center", gap: 2, flexShrink: 0 }}>
            <button aria-label="Sebelumnya" onClick={s.onPrev} style={{ ...btn, width: 34, height: 40, opacity: 0.85 }}><IcPrev s={19} /></button>
            <button aria-label={s.playing ? "Jeda" : "Putar"} onClick={s.onToggle} style={{ ...btn, width: 44, height: 44, borderRadius: "50%", background: "var(--accent)", boxShadow: "0 6px 18px rgba(var(--accent-rgb),0.5)" }}>
              {s.playing ? <IcPause s={19} /> : <IcPlay s={19} />}
            </button>
            <button aria-label="Berikutnya" onClick={s.onNext} style={{ ...btn, width: 34, height: 40, opacity: 0.85 }}><IcNext s={19} /></button>
            <button aria-label="Tutup player" onClick={s.onClose} style={{ ...btn, width: 30, height: 30, marginLeft: 2, borderRadius: "50%", background: "rgba(255,255,255,0.1)", color: "rgba(255,255,255,0.75)" }}><IcClose s={14} /></button>
          </div>
        </div>

        {/* Progress */}
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 3, background: "rgba(255,255,255,0.08)" }}>
          <div style={{ height: "100%", width: `${pct}%`, background: "linear-gradient(90deg,var(--accent),var(--accent-soft))", transition: "width .5s linear" }} />
        </div>
      </div>
    </div>
  );
};

// ─── FULL PLAYER ───────────────────────────────────────────────────────────
const FullPlayer = ({ player, songs, setSongs, onClose, playerBg, setPlayerBg }) => {
  const { currentSong, isPlaying, progress, duration, volume, setVolume, shuffle, setShuffle, repeat, setRepeat, togglePlay, playNext, playPrev, seek } = player;
  if (!currentSong) return null;
  const song   = songs.find(s => s.id === currentSong.id) || currentSong;
  const pct    = duration ? (progress / duration) * 100 : 0;
  const toggleLike = () => setSongs(prev => prev.map(s => s.id === currentSong.id ? { ...s, liked: !s.liked } : s));
  const bg = playerBg
    ? `linear-gradient(180deg,rgba(var(--bg-rgb),0.45) 0%,rgba(var(--bg-rgb),0.82) 55%,var(--bg) 100%), url(${playerBg}) center/cover no-repeat`
    : "radial-gradient(120% 60% at 50% 0%,var(--glow) 0%,var(--deep) 50%,var(--bg) 100%)";
  const glass = { width: 36, height: 36, borderRadius: "50%", border: "none", background: "rgba(255,255,255,0.14)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", fontSize: 13 };
  const track = (v) => ({ background: `linear-gradient(to right,var(--accent-soft) ${v}%,rgba(255,255,255,0.22) ${v}%)` });

  return (
    <div role="dialog" aria-label="Sedang diputar" style={{ position: "fixed", inset: 0, zIndex: 100, background: bg, overflowY: "auto", display: "flex", flexDirection: "column", padding: "calc(env(safe-area-inset-top,0px) + 14px) 22px calc(env(safe-area-inset-bottom,0px) + 24px)" }}>
      {/* Top */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
        <button onClick={onClose} aria-label="Tutup pemutar" style={glass}>
          <svg width={18} height={18} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div style={{ textAlign: "center", minWidth: 0 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "var(--accent-soft)", letterSpacing: 0.4 }}>Sedang diputar</div>
          <div style={{ fontSize: 13, color: "rgba(255,255,255,0.8)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: 170 }}>{currentSong.album || "Single"}</div>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {playerBg && <button onClick={() => setPlayerBg(null)} aria-label="Hapus foto banner" style={glass}><IcClose s={15} /></button>}
          <label aria-label="Ganti foto banner musik" style={glass}>
            <IcCamera s={15} />
            <input type="file" accept="image/*" style={{ display: "none" }} onChange={async e => { const f = e.target.files?.[0]; e.target.value = ""; if (f) { try { setPlayerBg(await readImage(f, 1200)); } catch {} } }} />
          </label>
        </div>
      </div>

      {/* Art: sampul + piringan hitam */}
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", padding: "18px 0", minHeight: 270 }}>
        <div style={{ position: "relative", width: 300, height: 248 }}>
          <div className="vinyl" style={{
            position: "absolute", left: 52, top: 0, width: 248, height: 248, borderRadius: "50%",
            display: "flex", alignItems: "center", justifyContent: "center",
            background: "repeating-radial-gradient(circle,#0c0a1a 0 2px,#1c1836 2px 4px)",
            boxShadow: "0 18px 40px rgba(0,0,0,0.5), inset 0 0 0 3px rgba(255,255,255,0.06)",
            animation: "spin 6s linear infinite", animationPlayState: isPlaying ? "running" : "paused",
          }}>
            <div style={{ width: 82, height: 82, borderRadius: "50%", background: "var(--accent)", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <div style={{ width: 12, height: 12, borderRadius: "50%", background: "var(--bg)" }} />
            </div>
            <div style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "conic-gradient(from 30deg,transparent 0 20%,rgba(255,255,255,0.08) 25%,transparent 30% 70%,rgba(255,255,255,0.08) 75%,transparent 80%)" }} />
          </div>
          <div style={{ position: "absolute", left: 0, top: 0, width: 248, height: 248, borderRadius: 24, overflow: "hidden", boxShadow: "0 24px 50px rgba(0,0,0,0.6)", transform: isPlaying ? "scale(1)" : "scale(0.94)", transition: "transform 0.45s ease" }}>
            <AlbumArt song={currentSong} size={248} style={{ borderRadius: 24 }} />
          </div>
        </div>
      </div>

      {/* Info */}
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div className="disp" style={{ fontSize: 24, fontWeight: 700, color: "#fff", lineHeight: 1.15, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{currentSong.title}</div>
          <div style={{ fontSize: 14, color: "rgba(255,255,255,0.75)", marginTop: 4, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{currentSong.artist}</div>
        </div>
        <button onClick={toggleLike} aria-label="Suka" aria-pressed={!!song.liked} style={{ background: "rgba(255,255,255,0.1)", border: "none", cursor: "pointer", width: 44, height: 44, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <IcHeart s={22} filled={song.liked} />
        </button>
      </div>

      {/* Seek */}
      <div style={{ marginBottom: 14 }}>
        <input className="seek" type="range" min={0} max={duration || 1} step={0.1} value={progress} aria-label="Posisi lagu"
          onChange={e => seek(Number(e.target.value))} style={track(pct)} />
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 6 }}>
          <span style={{ fontSize: 12, color: "rgba(255,255,255,0.7)" }}>{fmt(progress)}</span>
          <span style={{ fontSize: 12, color: "rgba(255,255,255,0.7)" }}>{fmt(duration)}</span>
        </div>
      </div>

      {/* Controls */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 22, padding: "0 4px" }}>
        <IconBtn icon={IcShuffle} onClick={() => setShuffle(s => !s)} active={shuffle} size={20} />
        <IconBtn icon={IcPrev}    onClick={playPrev} size={28} />
        <button onClick={togglePlay} aria-label={isPlaying ? "Jeda" : "Putar"} style={{ width: 76, height: 76, borderRadius: "50%", border: "none", cursor: "pointer", background: "var(--accent)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 30px rgba(var(--accent-rgb),0.45)" }}>
          {isPlaying ? <IcPause s={28} /> : <IcPlay s={28} />}
        </button>
        <IconBtn icon={IcNext}   onClick={playNext} size={28} />
        <IconBtn icon={IcRepeat} onClick={() => setRepeat(r => !r)} active={repeat} size={20} />
      </div>

      {/* Volume */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, background: "rgba(255,255,255,0.08)", borderRadius: 16, padding: "12px 16px" }}>
        <IcVolume s={16} />
        <input className="seek" type="range" min={0} max={100} value={volume} aria-label="Volume"
          onChange={e => setVolume(Number(e.target.value))} style={{ flex: 1, ...track(volume) }} />
        <span style={{ fontSize: 12, color: "rgba(255,255,255,0.7)", minWidth: 32, textAlign: "right" }}>{volume}%</span>
      </div>
    </div>
  );
};

